        mean2 = DataStatistics4.mean(data2)

        numerator = sum((data1[i] - mean1) * (data2[i] - mean2) for i in range(n))

        variance1 = sum((data1[i] - mean1) ** 2 for i in range(n))
        variance2 = sum((data2[i] - mean2) ** 2 for i in range(n))
        denominator = math.sqrt(variance1) * math.sqrt(variance2)

        if denominator == 0:
            return 0
        return numerator / denominator

    @staticmethod
    def skewness(data):
        """Replace Magic Number with Symbolic Constant: Use named constants for numeric literals"""
        n = len(data)
        mean_value = DataStatistics4.mean(data)
        variance = DataStatistics4._variance(data, mean_value)
        std_deviation = math.sqrt(variance)

