        numerator = sum_of_cubes * n
        denominator = (n - 1) * (n - 2) * std_deviation ** 3

        return numerator / denominator

    @staticmethod
    def kurtosis(data):
        n = len(data)
        mean_value = DataStatistics4.mean(data)
        std_deviation = math.sqrt(DataStatistics4._variance(data, mean_value))

        if std_deviation == 0:
            return math.nan

        # Introduce Explaining Variable: clearer code through naming
        centered_data = [x - mean_value for x in data]
        fourth_moment = sum(x ** 4 for x in centered_data) / n

        return fourth_moment / std_deviation ** 4 - 3

    @staticmethod
    def pdf(data, mu, sigma):
        """Replace Magic Number with Symbolic Constant: use symbolically named constant"""
        if sigma == 0:
            return [0] * len(data)

        # Introduce Explaining Variable: clearer code through naming
        sigma_sqrt_two_pi = sigma * DataStatistics4.NORMALIZATION_DENOMINATOR
        pdf_values = [
            (1 / sigma_sqrt_two_pi) * math.exp(-DataStatistics4.HALF * ((x - mu) / sigma) ** 2)
            for x in data
        ]
        return pdf_values
